using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using McpStdioServer.Tools;
using McpStdioServer.Prompts;

var builder = Host.CreateApplicationBuilder(args);

// Redirect all logging to stderr so stdout stays clean for JSON-RPC.
builder.Logging.ClearProviders();
builder.Logging.AddConsole(opts => opts.LogToStandardErrorThreshold = LogLevel.Trace);

builder.Services.AddHttpClient("ExternalApi", client =>
{
    client.BaseAddress = new Uri("https://api.example.com/");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
});

builder.Services
    .AddMcpServer(opts =>
    {
        opts.ServerInfo = new() { Name = "McpStdioServer", Version = "1.0.0" };
    })
    .WithStdioServerTransport()
    .WithTools<ApiTools>()
    .WithPrompts<SummarizationPrompts>();

await builder.Build().RunAsync();

