using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpStdioServer.Tools;

[McpServerToolType]
public sealed class ApiTools
{
    [McpServerTool, Description("Fetches data from an external API endpoint and returns the JSON response.")]
    public static async Task<string> FetchData(
        IHttpClientFactory httpClientFactory,
        ILogger<ApiTools> logger,
        [Description("The relative API path to call (e.g. \"users/1\").")] string path,
        CancellationToken cancellationToken)
    {
        logger.LogInformation("Calling external API: {Path}", path);

        using var client = httpClientFactory.CreateClient("ExternalApi");
        using var response = await client.GetAsync(path, cancellationToken);

        response.EnsureSuccessStatusCode();
        var json = await response.Content.ReadAsStringAsync(cancellationToken);

        logger.LogInformation("API call succeeded ({StatusCode})", (int)response.StatusCode);
        return json;
    }
}

using System.ComponentModel;
using ModelContextProtocol;
using ModelContextProtocol.Server;

namespace McpStdioServer.Prompts;

[McpServerPromptType]
public sealed class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt that asks the model to summarize the given text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Desired style: brief, detailed, or bullet-points.")] string style = "brief")
    {
        return
        [
            new(Role.User, $"""
                Summarize the following text using a "{style}" style.
                Return only the summary with no preamble.

                Text:
                {text}
                """)
        ];
    }
}

